import { GoogleGenAI, HarmCategory, HarmBlockThreshold } from "@google/genai";
import { AnalysisResult } from "../types";

// Initialize Gemini Client
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

// Use a model capable of Search Grounding
const MODEL_NAME = "gemini-2.5-flash";

const SYSTEM_INSTRUCTION = `
You are the AIEO (AI Information Engine Optimization) Engine. 
Your goal is to evaluate PR content based on how well it would be interpreted, summarized, and cited by LLM-based search engines.

You analyze text for:
1. Structure Readability
2. Data Presence
3. Coherence & Repetition
4. Snippetability

**OUTPUT FORMAT RULES:**
- **Output MUST be a valid JSON string.**
- Do NOT output markdown code blocks (like \`\`\`json). Just the raw JSON string.
- Structure your JSON exactly matching the interface below:

{
  "totalScore": number (0-100),
  "summary": "Detailed executive summary in Korean (min 300 chars)",
  "metrics": [
    { "name": "Metric Name in Korean", "score": number, "feedback": "Specific feedback in Korean", "status": "Good" | "Needs Improvement" | "Weak" }
  ],
  "snippets": [
