  ],
  "rewrites": {
    "basic": "Full length Blog Post style in Korean (Markdown)",
    "linkedin": "LinkedIn style in Korean (Markdown)",
    "newsroom": "Press Release style in Korean (Markdown)",
    "faq": "Q&A style in Korean (Markdown)",
    "tldr": "TL;DR style in Korean (Markdown)"
  },
  "checklists": {
